CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_dlyflow bigint,
    p_esccomprate numeric,
    p_interscore numeric,
    p_vendcount integer,
    p_mktspan integer
)
RETURNS numeric AS $$
BEGIN
    RETURN (p_dlyflow / 1000.0) + (p_esccomprate * 0.2) + (p_interscore * 0.3) + (p_vendcount * 0.1) - (p_mktspan / 100.0);
END;
$$ LANGUAGE plpgsql;

