CREATE OR REPLACE FUNCTION calculate_market_risk(p_mktregistry varchar)
RETURNS numeric AS $$
DECLARE
    v_dlyflow bigint;
    v_esccomprate numeric;
    v_interscore numeric;
    v_vendcount integer;
    v_mktspan integer;
BEGIN
    SELECT dlyflow, esccomprate, interscore, vendcount, mktspan
    INTO v_dlyflow, v_esccomprate, v_interscore, v_vendcount, v_mktspan
    FROM markets
    WHERE mktregistry = p_mktregistry;

    RETURN (v_dlyflow / 1000.0) + (v_esccomprate * 0.2) + (v_interscore * 0.3) + (v_vendcount * 0.1) - (v_mktspan / 100.0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(flow numeric, rates numeric, scores numeric, counts integer, lifespan integer)
RETURNS numeric AS $$
    SELECT (flow / 1000.0) + (rates * 0.2) + (scores * 0.3) + (counts * 0.1) - (lifespan / 100.0);
$$ LANGUAGE sql;

